{
  "items": [
    {
      "name": "Polynomial.iterate_derivative_map",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (f : R →+* S) (k : ℕ),\n  (⇑Polynomial.derivative)^[k] (Polynomial.map f p) = Polynomial.map f ((⇑Polynomial.derivative)^[k] p)"
    },
    {
      "name": "Polynomial.derivativeFinsupp_map",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (f : R →+* S),\n  Polynomial.derivativeFinsupp (Polynomial.map f p) =\n    Finsupp.mapRange (fun x => Polynomial.map f x) ⋯ (Polynomial.derivativeFinsupp p)"
    },
    {
      "name": "MvPowerSeries.mapAlgHom",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {R : Type u_2} →\n    {A : Type u_3} →\n      [inst : CommSemiring R] →\n        [inst_1 : Semiring A] →\n          [inst_2 : Algebra R A] →\n            {B : Type u_4} →\n              [inst_3 : Semiring B] → [inst_4 : Algebra R B] → (A →ₐ[R] B) → MvPowerSeries σ A →ₐ[R] MvPowerSeries σ B"
    },
    {
      "name": "MvPolynomial.pderiv_map",
      "module_name": "Mathlib.Algebra.MvPolynomial.PDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type v} [inst : CommSemiring R] {S : Type u_1} [inst_1 : CommSemiring S] {φ : R →+* S}\n  {f : MvPolynomial σ R} {i : σ},\n  (MvPolynomial.pderiv i) ((MvPolynomial.map φ) f) = (MvPolynomial.map φ) ((MvPolynomial.pderiv i) f)"
    },
    {
      "name": "MvPolynomial.mapAlgHom",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {S₂ : Type w} →\n      {σ : Type u_1} →\n        [inst : CommSemiring R] →\n          [inst_1 : CommSemiring S₁] →\n            [inst_2 : CommSemiring S₂] →\n              [inst_3 : Algebra R S₁] →\n                [inst_4 : Algebra R S₂] → (S₁ →ₐ[R] S₂) → MvPolynomial σ S₁ →ₐ[R] MvPolynomial σ S₂"
    },
    {
      "name": "MvPowerSeries.map",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {R : Type u_2} →\n    {S : Type u_3} → [inst : Semiring R] → [inst_1 : Semiring S] → (R →+* S) → MvPowerSeries σ R →+* MvPowerSeries σ S"
    },
    {
      "name": "Polynomial.derivative_map",
      "module_name": "Mathlib.Algebra.Polynomial.Derivative",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (f : R →+* S),\n  Polynomial.derivative (Polynomial.map f p) = Polynomial.map f (Polynomial.derivative p)"
    },
    {
      "name": "Polynomial.sumIDeriv_map",
      "module_name": "Mathlib.Algebra.Polynomial.SumIteratedDerivative",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (f : R →+* S),\n  Polynomial.sumIDeriv (Polynomial.map f p) = Polynomial.map f (Polynomial.sumIDeriv p)"
    }
  ]
}

